-- v3 rewrite seed content: 12 topics, 72 questions, from the
-- question-bank JSON provided for this rewrite (parts 1-2, topics
-- 01-12). Deterministic uuid5 ids (namespace
-- 6f8f7a2e-0000-4000-8000-000000000000, name `topic:<slug>` /
-- `question:<key>`) so re-running this file is idempotent and the
-- ids never depend on insertion order.

insert into public.topics (id, slug, order_index, title, subtitle, default_importance)
values
  ('596b3d1c-04cc-5d01-807f-979c919386ca', 'communication-conflict', 1, 'Communication & conflict', 'How you each handle disagreement, before it becomes a bigger conversation.', null),
  ('71303239-88ce-5730-945a-6e5857d6aafb', 'faith-practice', 2, 'Faith & practice', 'How you each practise, and what you expect of one another.', null),
  ('d74a0ca9-78c1-50db-8c82-8ff4d822d7d0', 'family-in-laws', 3, 'Family & in-laws', 'How present extended family will be in your day-to-day life.', null),
  ('43b0526b-141f-51e7-8e51-09a1cfd9c6fb', 'living-arrangements', 4, 'Living arrangements', 'Where you''ll live, and for how long.', null),
  ('2bbd6783-cf23-5e0b-b86d-62be4822eed4', 'home-household-roles', 5, 'Home & household roles', 'Who does what, and what ''normal'' looks like for each of you.', null),
  ('7bab8b85-410c-58d8-bb91-e9bfebdc2bd9', 'finances-debt', 6, 'Finances & debt', 'Money habits, debt, and how you''ll manage things together.', null),
  ('92506bc6-efc4-5faf-a7df-3553b24b73a8', 'children-parenting', 7, 'Children & parenting', 'Whether, when, and how you''d raise a family.', null),
  ('0fbc17fb-1ee6-572c-b31d-d06775fe562c', 'nikah-contract', 8, 'The nikah & marriage contract', 'Mahr, conditions, and the practical side of the marriage itself.', null),
  ('90fb0b64-1bdc-5036-957b-ec41e04b58a6', 'health-family-history', 9, 'Health & family history', 'What you''d each want to know, and when.', null),
  ('a949b8a2-6e65-5287-ae3c-14befd30e21b', 'work-earning-moving', 10, 'Work, earning & moving', 'Whose work leads, and how far it can take you.', null),
  ('c55ff2dc-8bf8-5fa8-90c0-f1c205cc89f6', 'social-life-boundaries', 11, 'Social life & boundaries', 'Friendships, time out, and what stays between you.', null),
