on conflict (id) do update set
  slug = excluded.slug,
  order_index = excluded.order_index,
  title = excluded.title,
  subtitle = excluded.subtitle,
  default_importance = excluded.default_importance;

insert into public.questions (id, topic_id, key, order_index, text, options, starter_discuss)
values
  ('75641e9f-a5d7-5eff-a7ff-85e3752fcf36', '596b3d1c-04cc-5d01-807f-979c919386ca', 'comm-01', 1, 'When something upsets you, what do you tend to do first?',
    '[{"key": "a", "label": "Say it right away", "description": "I''d rather raise it in the moment.", "cluster": "immediate"}, {"key": "b", "label": "Pause, then raise it", "description": "A few minutes to gather myself first.", "cluster": "immediate"}, {"key": "c", "label": "Wait until things are calm", "description": "Later that day, or the next.", "cluster": "delayed"}, {"key": "d", "label": "Let it pass unless it repeats", "description": "I''ll raise it only if it becomes a pattern.", "cluster": "delayed"}]'::jsonb,
    'You reach for different timings when something stings. Try agreeing on a signal that means ''not now, but soon'' — it protects both instincts.'),
  ('55ed8914-692b-5edd-8188-6affa5f3030a', '596b3d1c-04cc-5d01-807f-979c919386ca', 'comm-02', 2, 'In the middle of a disagreement, what helps you most?',
    '[{"key": "a", "label": "Talking until it''s settled", "description": "I don''t like leaving things open.", "cluster": "engage"}, {"key": "b", "label": "Talking, with breaks", "description": "Keep going, but pause when it gets heated.", "cluster": "engage"}, {"key": "c", "label": "Time apart first", "description": "I need to step away before I can talk well.", "cluster": "space"}, {"key": "d", "label": "Writing before speaking", "description": "I think more clearly on paper.", "cluster": "space"}]'::jsonb,
    'One of you settles by staying in it; the other by stepping out. Talk about what a break should look like so it doesn''t read as walking away.'),
  ('3901099a-0e88-50bf-b09b-e79db9f17de7', '596b3d1c-04cc-5d01-807f-979c919386ca', 'comm-03', 3, 'If something is unresolved at bedtime, what happens?',
    '[{"key": "a", "label": "We stay up until it''s settled", "description": "I couldn''t sleep on it.", "cluster": "resolve"}, {"key": "b", "label": "We set a time tomorrow", "description": "Named and agreed before we sleep.", "cluster": "resolve"}, {"key": "c", "label": "We let it rest", "description": "See how it feels in the morning.", "cluster": "rest"}, {"key": "d", "label": "We move on", "description": "Most things don''t need returning to.", "cluster": "rest"}]'::jsonb,
    'This one causes more late nights than almost anything. Decide now what happens at 11pm, while neither of you is upset.'),
  ('6a26c131-c6f1-5c95-be62-371934b0a7a7', '596b3d1c-04cc-5d01-807f-979c919386ca', 'comm-04', 4, 'If the marriage hit a difficult stretch, who would you talk to?',
    '[{"key": "a", "label": "No one outside us", "description": "What''s between us stays between us.", "cluster": "closed"}, {"key": "b", "label": "One trusted person", "description": "A single friend or sibling I rely on.", "cluster": "closed"}, {"key": "c", "label": "Our families", "description": "They''d know, and they''d help.", "cluster": "open"}, {"key": "d", "label": "An imam or counsellor", "description": "Someone outside the family, with experience.", "cluster": "open"}]'::jsonb,
    'Who gets to know is worth settling early. Try agreeing on one person each of you could turn to, named in advance.'),
  ('6092a9b0-c4b4-5ab3-b3dc-389268139f26', '596b3d1c-04cc-5d01-807f-979c919386ca', 'comm-05', 5, 'When you''re clearly upset, how do you want to be approached?',
    '[{"key": "a", "label": "Ask me directly", "description": "Just ask what''s wrong.", "cluster": "direct"}, {"key": "b", "label": "Give me a moment, then ask", "description": "A little space first, then check in.", "cluster": "direct"}, {"key": "c", "label": "Wait for me", "description": "I''ll come to you when I''m ready.", "cluster": "wait"}, {"key": "d", "label": "Something kind, unspoken", "description": "Show care without making me explain.", "cluster": "wait"}]'::jsonb,
    'What feels like care to one person can feel like pressure to the other. Say plainly what you want the first five minutes to look like.'),
  ('dedae550-44e7-5354-962d-e786311da499', '596b3d1c-04cc-5d01-807f-979c919386ca', 'comm-06', 6, 'How do you feel about raised voices during an argument?',
    '[{"key": "a", "label": "Never acceptable", "description": "It changes how safe the conversation feels.", "cluster": "low"}, {"key": "b", "label": "Rare, not a habit", "description": "It happens, but it shouldn''t be normal.", "cluster": "low"}, {"key": "c", "label": "Normal where I''m from", "description": "Volume doesn''t mean much in my family.", "cluster": "tolerant"}, {"key": "d", "label": "Better than silence", "description": "I''d rather hear it than be shut out.", "cluster": "tolerant"}]'::jsonb,
    'Households run at different volumes, and it''s usually inherited rather than chosen. Describe what arguments sounded like growing up before deciding what yours will sound like.'),
  ('a3f9c076-ed0b-5b64-994f-8e8c5b1302f3', '71303239-88ce-5730-945a-6e5857d6aafb', 'faith-01', 1, 'How do you picture salah working in our home?',
    '[{"key": "a", "label": "Together whenever we''re both home", "description": "Praying in congregation as our default.", "cluster": "together"}, {"key": "b", "label": "Together for some prayers", "description": "Fajr and maghrib together, the rest as they fall.", "cluster": "together"}, {"key": "c", "label": "Each to our own routine", "description": "We pray, but not necessarily side by side.", "cluster": "individual"}, {"key": "d", "label": "One leads, the other joins when they can", "description": "Open invitation rather than expectation.", "cluster": "individual"}]'::jsonb,
    'Praying together is a habit that forms in the first months or not at all. Try picking one prayer to start with rather than settling the whole week.'),
  ('3c5d30ad-bdb6-57ed-ae9e-3b8b4f60cb97', '71303239-88ce-5730-945a-6e5857d6aafb', 'faith-02', 2, 'How would you want Ramadan to run in our home?',
    '[{"key": "a", "label": "Built around the two of us", "description": "Our own rhythm for suhoor and iftar.", "cluster": "couple"}, {"key": "b", "label": "Ours, with family nights", "description": "Mostly us, with regular family gatherings.", "cluster": "couple"}, {"key": "c", "label": "Mostly with extended family", "description": "Ramadan is a family season for me.", "cluster": "wider"}, {"key": "d", "label": "Each keeping our own routine", "description": "Work and schedules differ; we''d adapt.", "cluster": "wider"}]'::jsonb,
    'Ramadan is where two family traditions meet hardest. Walk through one week of it out loud — suhoor, iftar, taraweeh — before the first one arrives.'),
  ('24602300-c70d-5037-a4ed-5d3175e66995', '71303239-88ce-5730-945a-6e5857d6aafb', 'faith-03', 3, 'How would you want to keep learning your deen?',
    '[{"key": "a", "label": "Studying together", "description": "Classes or a regular halaqa, as a pair.", "cluster": "structured"}, {"key": "b", "label": "Each of us, on our own", "description": "Reading and listening in my own time.", "cluster": "individual"}, {"key": "c", "label": "Through community", "description": "Whatever the masjid or circle is running.", "cluster": "structured"}, {"key": "d", "label": "Not something I plan formally", "description": "It happens as life brings it.", "cluster": "individual"}]'::jsonb,
    'Learning together is one of the easier habits to build early. Try one thing you could both commit to for a month, not a year.'),
  ('9f56474b-426b-5fae-8fa5-f23ec80cc46f', '71303239-88ce-5730-945a-6e5857d6aafb', 'faith-04', 4, 'If one of us wanted to change something about how we practise, what would you expect?',
    '[{"key": "a", "label": "We decide together", "description": "It affects both of us, so we agree it.", "cluster": "joint"}, {"key": "b", "label": "Consulted, but it''s personal", "description": "Tell me, but it''s ultimately yours.", "cluster": "joint"}, {"key": "c", "label": "Each person''s own business", "description": "I wouldn''t expect a conversation.", "cluster": "individual"}, {"key": "d", "label": "We''d seek guidance together", "description": "Ask someone knowledgeable, as a pair.", "cluster": "individual"}]'::jsonb,
    'Practice changes over a marriage, usually gradually. Agree on how you''d want to hear about it, rather than what the change should be.'),
  ('a493205f-ff19-54a1-8d41-c49458d60abc', '71303239-88ce-5730-945a-6e5857d6aafb', 'faith-05', 5, 'How much of our week would involve the masjid or community?',
    '[{"key": "a", "label": "Central to it", "description": "Several times a week.", "cluster": "high"}, {"key": "b", "label": "Regular, not central", "description": "Weekly, or thereabouts.", "cluster": "high"}, {"key": "c", "label": "Occasional", "description": "Eid, Ramadan, particular events.", "cluster": "low"}, {"key": "d", "label": "Not something I seek out", "description": "My practice is mostly at home.", "cluster": "low"}]'::jsonb,
    'Community involvement shapes your week more than it looks on paper. Compare what a typical Saturday would actually contain for each of you.'),
  ('c0002570-4510-56d7-9930-0e981778e200', '71303239-88ce-5730-945a-6e5857d6aafb', 'faith-06', 6, 'How do you feel about differences between us in how we practise?',
    '[{"key": "a", "label": "I''d want us closely matched", "description": "Similar habits make it easier.", "cluster": "matched"}, {"key": "b", "label": "I''d expect us to grow together", "description": "Differences now, converging over time.", "cluster": "matched"}, {"key": "c", "label": "Small differences are fine", "description": "We don''t need identical routines.", "cluster": "flexible"}, {"key": "d", "label": "Differences are fine, with respect", "description": "As long as neither of us pushes the other.", "cluster": "flexible"}]'::jsonb,
    'This one is about expectation, not level. Talk about what you''d each find hard to live alongside, rather than who is doing more.'),
  ('f34437e7-9221-532e-becc-7fd7d0ab222d', 'd74a0ca9-78c1-50db-8c82-8ff4d822d7d0', 'fam-01', 1, 'How often would you want to see each set of parents?',
    '[{"key": "a", "label": "Most days, if they''re near", "description": "Dropping in is normal for us.", "cluster": "frequent"}, {"key": "b", "label": "Weekly", "description": "A regular fixture in the week.", "cluster": "frequent"}, {"key": "c", "label": "A few times a month", "description": "Planned rather than spontaneous.", "cluster": "spaced"}, {"key": "d", "label": "Occasions and holidays", "description": "Eid, celebrations, when we travel.", "cluster": "spaced"}]'::jsonb,
    'Frequency is easier to agree than principle. Try naming a number of visits per month for each side, and adjust from there.'),
  ('c43d22ac-2064-51be-82a6-a3a5f0caa0dd', 'd74a0ca9-78c1-50db-8c82-8ff4d822d7d0', 'fam-02', 2, 'How involved should parents be in day-to-day decisions?',
    '[{"key": "a", "label": "We decide as a wider family", "description": "Their input is part of how we decide.", "cluster": "involved"}, {"key": "b", "label": "Consulted on big things", "description": "Major decisions include them; daily life is ours.", "cluster": "involved"}, {"key": "c", "label": "Informed, not consulted", "description": "We share the outcome, not the deliberation.", "cluster": "independent"}, {"key": "d", "label": "Between us only", "description": "Our household decisions stay with us.", "cluster": "independent"}]'::jsonb,
    'You both value family closeness — you differ on where the line sits. Try describing what ''involved'' looks like on a normal Tuesday, not at a crisis.'),
  ('30f19acf-7016-5056-823f-086408686c04', 'd74a0ca9-78c1-50db-8c82-8ff4d822d7d0', 'fam-03', 3, 'If a parent needed to live with us, what would you want?',
    '[{"key": "a", "label": "Of course, without question", "description": "It''s what family is for.", "cluster": "open"}, {"key": "b", "label": "Yes, discussed first", "description": "Willing, but planned together.", "cluster": "open"}, {"key": "c", "label": "Only if there were no alternative", "description": "A last resort rather than a first.", "cluster": "reluctant"}, {"key": "d", "label": "I''d look for another arrangement", "description": "Support them, but not in our home.", "cluster": "reluctant"}]'::jsonb,
    'This usually arrives with no notice. Agreeing the principle now is easier than deciding it in a hospital corridor.'),
  ('810464e0-828c-5e96-b96d-2d17aebac47f', 'd74a0ca9-78c1-50db-8c82-8ff4d822d7d0', 'fam-04', 4, 'How should we handle financial support to family?',
    '[{"key": "a", "label": "A fixed monthly amount", "description": "Agreed together, budgeted for.", "cluster": "planned"}, {"key": "b", "label": "Whatever is needed", "description": "We give when there''s a need.", "cluster": "open"}, {"key": "c", "label": "Case by case, discussed", "description": "Each request talked through first.", "cluster": "planned"}, {"key": "d", "label": "Emergencies only", "description": "Not a regular commitment.", "cluster": "limited"}]'::jsonb,
    'Money to family is one of the most common quiet resentments in a marriage. Put a number and a rule on it while it''s still hypothetical.'),
  ('a1e4297d-a8a4-5e73-b7fc-1db6e7d26a4b', 'd74a0ca9-78c1-50db-8c82-8ff4d822d7d0', 'fam-05', 5, 'If your family and your spouse disagreed, what would you do?',
    '[{"key": "a", "label": "Side with my spouse", "description": "We''re the household now.", "cluster": "spouse"}, {"key": "b", "label": "Mediate without taking sides", "description": "Try to hold both.", "cluster": "spouse"}, {"key": "c", "label": "Hear my family out first", "description": "Understand their position before responding.", "cluster": "family"}, {"key": "d", "label": "It depends on the issue", "description": "No general rule.", "cluster": "family"}]'::jsonb,
    'Nobody wants to be chosen against. Talk about what support would feel like from the outside, rather than who is right.'),
  ('6864dd1d-986d-57d9-bc38-a54efb2b26e1', 'd74a0ca9-78c1-50db-8c82-8ff4d822d7d0', 'fam-06', 6, 'How much would our families know about our marriage?',
    '[{"key": "a", "label": "Very little", "description": "What''s between us stays between us.", "cluster": "private"}, {"key": "b", "label": "Good news, not difficulties", "description": "They''d hear the happy parts.", "cluster": "private"}, {"key": "c", "label": "Most things", "description": "We''re close; they''d know.", "cluster": "open"}, {"key": "d", "label": "Whatever comes up", "description": "No particular filter.", "cluster": "open"}]'::jsonb,
    'One of you may assume privacy while the other assumes closeness. Agree what counts as ours before something difficult happens.'),
  ('d4b245fb-5ed3-585a-8d54-7a98d219b8b9', '43b0526b-141f-51e7-8e51-09a1cfd9c6fb', 'live-01', 1, 'Where would you want to live in the first two years?',
    '[{"key": "a", "label": "Our own place, just us", "description": "Independent from the start.", "cluster": "own"}, {"key": "b", "label": "Near one of our families", "description": "Our own place, but close by.", "cluster": "near"}, {"key": "c", "label": "With family for a while", "description": "Save first, move out later.", "cluster": "near"}, {"key": "d", "label": "Wherever work takes us", "description": "Location follows opportunity.", "cluster": "own"}]'::jsonb,
    'The first two years set habits that are hard to change later. Try agreeing an end date for whatever arrangement you start with.'),
  ('cd9409d2-3047-56a9-9a53-e4160f059bd7', '43b0526b-141f-51e7-8e51-09a1cfd9c6fb', 'live-02', 2, 'What kind of place suits you?',
    '[{"key": "a", "label": "A big city", "description": "Density, options, community.", "cluster": "urban"}, {"key": "b", "label": "A smaller city or town", "description": "Quieter, still connected.", "cluster": "urban"}, {"key": "c", "label": "Suburbs", "description": "Space, schools, calm.", "cluster": "quiet"}, {"key": "d", "label": "Somewhere rural", "description": "Away from it all.", "cluster": "quiet"}]'::jsonb,
    'Access to a masjid, halal food and community often decides this more than preference does. Check what each option would actually mean day to day.'),
  ('3ea61009-3a80-57e7-8e6b-b66ede258dcf', '43b0526b-141f-51e7-8e51-09a1cfd9c6fb', 'live-03', 3, 'Renting or buying?',
    '[{"key": "a", "label": "Buy as soon as we can", "description": "Ownership is a priority.", "cluster": "buy"}, {"key": "b", "label": "Buy when it makes sense", "description": "When the finances are right.", "cluster": "buy"}, {"key": "c", "label": "Rent for now", "description": "Flexibility matters more.", "cluster": "rent"}, {"key": "d", "label": "No strong feeling", "description": "Whatever suits at the time.", "cluster": "rent"}]'::jsonb,
    'This connects to how you''d finance it — worth reading alongside the riba question in Finances rather than on its own.'),
  ('5ec6cb86-6690-5c05-b67a-47c4961f38f7', '43b0526b-141f-51e7-8e51-09a1cfd9c6fb', 'live-04', 4, 'Would you move to another country?',
    '[{"key": "a", "label": "Yes, readily", "description": "I''d welcome it.", "cluster": "mobile"}, {"key": "b", "label": "Yes, if we both agreed", "description": "For the right reason.", "cluster": "mobile"}, {"key": "c", "label": "Only for something exceptional", "description": "A very high bar.", "cluster": "rooted"}, {"key": "d", "label": "I''d rather stay", "description": "This is home.", "cluster": "rooted"}]'::jsonb,
    'Migration is rarely theoretical for long. Talk about what would have to be true for the answer to change.'),
  ('ab6e4427-8ce9-562b-9be5-efd3893b77a7', '43b0526b-141f-51e7-8e51-09a1cfd9c6fb', 'live-05', 5, 'How close to family is right?',
    '[{"key": "a", "label": "Same street or building", "description": "As close as possible.", "cluster": "close"}, {"key": "b", "label": "Same neighbourhood", "description": "Walking distance.", "cluster": "close"}, {"key": "c", "label": "Same city, different area", "description": "A short drive.", "cluster": "distance"}, {"key": "d", "label": "A different city", "description": "Visits rather than drop-ins.", "cluster": "distance"}]'::jsonb,
    'Distance quietly decides how often people visit. Compare this with your answers on visit frequency — they should agree with each other.'),
  ('49e5ab8f-f773-5c22-8a5f-7708577c1a7a', '43b0526b-141f-51e7-8e51-09a1cfd9c6fb', 'live-06', 6, 'How often would guests be in our home?',
    '[{"key": "a", "label": "Often — an open house", "description": "People coming and going.", "cluster": "open"}, {"key": "b", "label": "Regularly, planned", "description": "Hosting, but with notice.", "cluster": "open"}, {"key": "c", "label": "Occasionally", "description": "A few times a month.", "cluster": "private"}, {"key": "d", "label": "Rarely", "description": "Home is where I switch off.", "cluster": "private"}]'::jsonb,
    'Hosting is generous and exhausting in different measures for different people. Talk about who does the work when guests come, not just how often.'),
  ('765d0fb3-f5a4-5530-b044-bb2477f4b6c8', '2bbd6783-cf23-5e0b-b86d-62be4822eed4', 'home-01', 1, 'Who cooks on a normal weekday?',
    '[{"key": "a", "label": "Mostly one of us", "description": "By preference, not obligation.", "cluster": "one"}, {"key": "b", "label": "Whoever is home first", "description": "Practical, not fixed.", "cluster": "shared"}, {"key": "c", "label": "Split evenly", "description": "Roughly half each.", "cluster": "shared"}, {"key": "d", "label": "Often help or takeaway", "description": "Neither of us wants to cook nightly.", "cluster": "outsourced"}]'::jsonb,
    'Cooking is the chore most likely to become invisible. Try tracking a real week before deciding what''s fair.'),
  ('f8127cb2-cef0-50b2-b525-71e3e52c3a3f', '2bbd6783-cf23-5e0b-b86d-62be4822eed4', 'home-02', 2, 'How should cleaning and upkeep work?',
    '[{"key": "a", "label": "One of us leads", "description": "Owned by one person.", "cluster": "one"}, {"key": "b", "label": "Split by task", "description": "Each has their areas.", "cluster": "shared"}, {"key": "c", "label": "Whoever notices", "description": "Informal and responsive.", "cluster": "shared"}, {"key": "d", "label": "We''d pay for help", "description": "Outsource what we can.", "cluster": "outsourced"}]'::jsonb,
    '''Whoever notices'' usually means whoever has the lower tolerance for mess. Check whether that''s a system or an accident.'),
  ('9b539d03-60e9-50e0-a87e-aab7e7bf4822', '2bbd6783-cf23-5e0b-b86d-62be4822eed4', 'home-03', 3, 'If we both work full time, who adjusts when life gets busy?',
    '[{"key": "a", "label": "Whoever earns less", "description": "The practical calculation.", "cluster": "one-adjusts"}, {"key": "b", "label": "Whoever has flexibility", "description": "Whichever job bends more easily.", "cluster": "one-adjusts"}, {"key": "c", "label": "We''d both cut back", "description": "Share the cost equally.", "cluster": "both"}, {"key": "d", "label": "Neither — we''d get help", "description": "Buy the time instead.", "cluster": "both"}]'::jsonb,
    'The person who adjusts once usually keeps adjusting. Talk about how you''d notice if that happened.'),
  ('fcc391ac-9589-50cf-ad90-c8a24658388a', '2bbd6783-cf23-5e0b-b86d-62be4822eed4', 'home-04', 4, 'Who handles household admin — bills, appointments, paperwork?',
    '[{"key": "a", "label": "One of us owns it", "description": "Simpler with a single point.", "cluster": "one"}, {"key": "b", "label": "Split by area", "description": "Each of us takes some categories.", "cluster": "shared"}, {"key": "c", "label": "Whoever has time", "description": "Flexible.", "cluster": "shared"}, {"key": "d", "label": "Neither of us enjoys it", "description": "We''d need a system.", "cluster": "one"}]'::jsonb,
    'Admin is real work that rarely gets counted. Try listing every recurring task once — the list is usually longer than either of you expects.'),
  ('bf53c933-7f1c-5309-8a68-f18a9b3ec201', '2bbd6783-cf23-5e0b-b86d-62be4822eed4', 'home-05', 5, 'How tidy does home need to be?',
    '[{"key": "a", "label": "Tidy at all times", "description": "I can''t settle otherwise.", "cluster": "high"}, {"key": "b", "label": "Tidy in shared spaces", "description": "Private rooms are yours.", "cluster": "high"}, {"key": "c", "label": "Lived-in is fine", "description": "Comfortable over pristine.", "cluster": "relaxed"}, {"key": "d", "label": "I don''t notice much", "description": "It isn''t on my radar.", "cluster": "relaxed"}]'::jsonb,
    'Different thresholds mean one person always cleans first. Name a standard for shared rooms only — it''s the fixable part.'),
  ('ece180ce-7976-581a-8bcf-599c63587b24', '2bbd6783-cf23-5e0b-b86d-62be4822eed4', 'home-06', 6, 'If one of us isn''t pulling their weight, how should it be raised?',
    '[{"key": "a", "label": "Directly, straight away", "description": "Say it when it happens.", "cluster": "direct"}, {"key": "b", "label": "Once it''s a pattern", "description": "Not over a single week.", "cluster": "direct"}, {"key": "c", "label": "Adjust quietly", "description": "Pick up the slack and move on.", "cluster": "indirect"}, {"key": "d", "label": "In a planned conversation", "description": "Sat down, not in the moment.", "cluster": "indirect"}]'::jsonb,
    'Quiet adjustment is the most common route to resentment. Agree on a low-stakes way to raise it before it needs raising.'),
  ('21dd0237-82cf-5799-95aa-dc94250bf1d6', '7bab8b85-410c-58d8-bb91-e9bfebdc2bd9', 'fin-01', 1, 'How should money work between us after the nikah?',
    '[{"key": "a", "label": "Fully joint", "description": "One pot, everything shared.", "cluster": "joint"}, {"key": "b", "label": "Joint plus personal", "description": "Shared costs joint, some money our own.", "cluster": "joint"}, {"key": "c", "label": "Separate, splitting costs", "description": "Our own accounts, agreed contributions.", "cluster": "separate"}, {"key": "d", "label": "One of us manages it", "description": "Single person handles the household finances.", "cluster": "separate"}]'::jsonb,
    'There''s no right structure, only a clear one. Try running a real month on paper under each approach.'),
  ('93bfc44c-bd08-52cc-be7a-6c8dafae42ef', '7bab8b85-410c-58d8-bb91-e9bfebdc2bd9', 'fin-02', 2, 'What happens to debt either of us brings in?',
    '[{"key": "a", "label": "Ours to clear together", "description": "We take it on as a household.", "cluster": "shared"}, {"key": "b", "label": "Each our own, openly", "description": "Separate, but nothing hidden.", "cluster": "shared"}, {"key": "c", "label": "Each our own, privately", "description": "It stays personal.", "cluster": "individual"}, {"key": "d", "label": "Depends on size and kind", "description": "Student loan and credit card aren''t the same.", "cluster": "individual"}]'::jsonb,
    'Whatever the structure, disclosure should come first. Agree on when each of you will actually say the number out loud.'),
  ('7dc5dcc8-b8b4-58f0-921a-42fdb97bd364', '7bab8b85-410c-58d8-bb91-e9bfebdc2bd9', 'fin-03', 3, 'What size of purchase needs a conversation first?',
    '[{"key": "a", "label": "Anything beyond small", "description": "We check in on most things.", "cluster": "tight"}, {"key": "b", "label": "Anything significant to our budget", "description": "A proportion, not a fixed sum.", "cluster": "tight"}, {"key": "c", "label": "Major commitments only", "description": "Car, property, big travel.", "cluster": "loose"}, {"key": "d", "label": "We each spend freely", "description": "Within our own money.", "cluster": "loose"}]'::jsonb,
    'This is easier as a number than a principle. Pick an amount tonight, and revisit it in a year.'),
  ('3d8591cd-cdef-5020-9f9d-b2eb33493f49', '7bab8b85-410c-58d8-bb91-e9bfebdc2bd9', 'fin-04', 4, 'How would you want us to approach interest-based finance?',
    '[{"key": "a", "label": "Avoid it entirely", "description": "Whatever the cost or inconvenience.", "cluster": "avoid"}, {"key": "b", "label": "Avoid where alternatives exist", "description": "Practical avoidance.", "cluster": "pragmatic"}, {"key": "c", "label": "Use Islamic finance where available", "description": "Seek out the structured alternatives.", "cluster": "avoid"}, {"key": "d", "label": "Decide case by case", "description": "Weigh each situation as it comes.", "cluster": "pragmatic"}]'::jsonb,
    'This shapes housing more than anything else you''ll decide. Look at what''s actually available to you locally before settling a position.'),
  ('1a802964-9ab7-54b9-a5ce-cdd97a90a3ec', '7bab8b85-410c-58d8-bb91-e9bfebdc2bd9', 'fin-05', 5, 'How do you approach saving?',
    '[{"key": "a", "label": "A fixed amount, first", "description": "Saved before anything is spent.", "cluster": "structured"}, {"key": "b", "label": "Whatever''s left", "description": "Save at the end of the month.", "cluster": "loose"}, {"key": "c", "label": "For specific goals", "description": "Saving when there''s something to save for.", "cluster": "structured"}, {"key": "d", "label": "Not a priority yet", "description": "Other things come first right now.", "cluster": "loose"}]'::jsonb,
    'Savers and spenders can live together well, but not accidentally. Set one automatic transfer and leave the rest flexible.'),
  ('08c3dc27-1273-5a4d-be07-8cda8fb3ab7c', '7bab8b85-410c-58d8-bb91-e9bfebdc2bd9', 'fin-06', 6, 'If one of us earns considerably more, how should that work?',
    '[{"key": "a", "label": "All household money", "description": "Income is shared regardless of source.", "cluster": "pooled"}, {"key": "b", "label": "Proportional contributions", "description": "Each contributes by share of income.", "cluster": "pooled"}, {"key": "c", "label": "Equal contributions", "description": "Same amount from each of us.", "cluster": "split"}, {"key": "d", "label": "The higher earner decides", "description": "They direct how it''s used.", "cluster": "split"}]'::jsonb,
    'Income gaps usually widen over a marriage. Decide the principle now, while neither of you knows who it will favour.'),
  ('191a0036-4497-5b26-a1e1-8703fc87f7fc', '92506bc6-efc4-5faf-a7df-3553b24b73a8', 'kids-01', 1, 'When would you want to have children?',
    '[{"key": "a", "label": "Straight away", "description": "As soon as we''re married.", "cluster": "soon"}, {"key": "b", "label": "Within a couple of years", "description": "Settle first, then start.", "cluster": "soon"}, {"key": "c", "label": "After a few years", "description": "Time as a couple first.", "cluster": "later"}, {"key": "d", "label": "Unsure, or not for a long time", "description": "Not something I''ve fixed.", "cluster": "later"}]'::jsonb,
    'Timing is one of the few things here with a real clock on it. Talk about what each of you wants settled before children arrive.'),
  ('cc6d3937-28c0-5712-a421-902327dc7894', '92506bc6-efc4-5faf-a7df-3553b24b73a8', 'kids-02', 2, 'How many children feels right to you?',
    '[{"key": "a", "label": "One or two", "description": "A small family.", "cluster": "small"}, {"key": "b", "label": "Three or four", "description": "A full house.", "cluster": "large"}, {"key": "c", "label": "As many as we''re given", "description": "No number in mind.", "cluster": "large"}, {"key": "d", "label": "I''d rather not fix a number", "description": "See how it goes.", "cluster": "open"}]'::jsonb,
    'Numbers usually shift once the first arrives. Talk about the first two rather than the total.'),
  ('e88a2f74-0c8c-52a9-8f83-079ff6f59b3a', '92506bc6-efc4-5faf-a7df-3553b24b73a8', 'kids-03', 3, 'If having children proved difficult, what would you want?',
    '[{"key": "a", "label": "Explore every option", "description": "Medical routes, as far as they go.", "cluster": "pursue"}, {"key": "b", "label": "Some options, within limits", "description": "Try, but with a line.", "cluster": "pursue"}, {"key": "c", "label": "Consider fostering or adoption", "description": "Another route to a family.", "cluster": "alternative"}, {"key": "d", "label": "Accept it and move forward", "description": "Build a life either way.", "cluster": "alternative"}]'::jsonb,
    'This is a hard thing to discuss in the abstract and harder in the moment. Agree only that you''d face it together and revisit it then.'),
  ('ba026fdf-66c7-5e72-80d5-c20d1a775e47', '92506bc6-efc4-5faf-a7df-3553b24b73a8', 'kids-04', 4, 'How would you want children educated?',
    '[{"key": "a", "label": "Islamic school", "description": "Faith-based throughout.", "cluster": "faith-led"}, {"key": "b", "label": "State school plus madrasah", "description": "Mainstream weekdays, deen at weekends.", "cluster": "mixed"}, {"key": "c", "label": "Home education", "description": "Taught at home.", "cluster": "faith-led"}, {"key": "d", "label": "Whatever is best locally", "description": "Decided by what''s available.", "cluster": "mixed"}]'::jsonb,
    'Schooling is decided by geography as much as principle. Look at what actually exists where you plan to live.'),
  ('920d3505-552c-55fb-ac38-838ce437c08e', '92506bc6-efc4-5faf-a7df-3553b24b73a8', 'kids-05', 5, 'What kind of discipline feels right to you?',
    '[{"key": "a", "label": "Firm and consistent", "description": "Clear rules, held to.", "cluster": "firm"}, {"key": "b", "label": "Clear rules, room to negotiate", "description": "Structure with flexibility.", "cluster": "firm"}, {"key": "c", "label": "Gentle, through conversation", "description": "Explaining rather than enforcing.", "cluster": "gentle"}, {"key": "d", "label": "How we were each raised", "description": "Follow what we know.", "cluster": "gentle"}]'::jsonb,
    'Most people parent the way they were parented until they choose otherwise. Compare what each of your childhoods actually looked like.'),
  ('92fbed22-9e9e-592d-9a05-e46a81a6048d', '92506bc6-efc4-5faf-a7df-3553b24b73a8', 'kids-06', 6, 'Who takes primary care in the early years?',
    '[{"key": "a", "label": "One of us at home", "description": "Full time, at least at first.", "cluster": "parent-led"}, {"key": "b", "label": "One of us reduces hours", "description": "Part time rather than stopping.", "cluster": "parent-led"}, {"key": "c", "label": "Both working, with childcare", "description": "Nursery or a childminder.", "cluster": "shared-care"}, {"key": "d", "label": "Family would help a lot", "description": "Grandparents in the week.", "cluster": "shared-care"}]'::jsonb,
    'This has a cost either way — money or career. Put rough numbers to both before deciding which one you''d rather pay.'),
  ('975e0890-71d0-5f55-9ee3-8f9ea1c6b7c9', '0fbc17fb-1ee6-572c-b31d-d06775fe562c', 'nikah-01', 1, 'How should the mahr be decided?',
    '[{"key": "a", "label": "The bride names it", "description": "Her decision, and that''s final.", "cluster": "couple"}, {"key": "b", "label": "Agreed between us", "description": "Discussed and settled together.", "cluster": "couple"}, {"key": "c", "label": "Families involved", "description": "Discussed across both families.", "cluster": "families"}, {"key": "d", "label": "What''s customary for us", "description": "Follow the norm in our families.", "cluster": "families"}]'::jsonb,
    'Mahr is a right, not a negotiation over worth. Talk about who you each expect to be in the room when it''s discussed.'),
  ('b131e5ee-c901-5c06-8048-92c90e81e188', '0fbc17fb-1ee6-572c-b31d-d06775fe562c', 'nikah-02', 2, 'What form would you want the mahr to take?',
    '[{"key": "a", "label": "A sum of money", "description": "Straightforward and clear.", "cluster": "material"}, {"key": "b", "label": "Gold or property", "description": "Something held rather than spent.", "cluster": "material"}, {"key": "c", "label": "Something non-material", "description": "A commitment rather than an asset.", "cluster": "non-material"}, {"key": "d", "label": "Part now, part deferred", "description": "Split between immediate and later.", "cluster": "deferred"}]'::jsonb,
    'The form matters less than both of you understanding it the same way. Say out loud what each option would mean in practice.'),
  ('9714eeaf-af85-549a-ad21-d92865066f24', '0fbc17fb-1ee6-572c-b31d-d06775fe562c', 'nikah-03', 3, 'Would you want conditions written into the contract?',
    '[{"key": "a", "label": "Yes, several", "description": "There are things I''d want recorded.", "cluster": "conditions"}, {"key": "b", "label": "One or two", "description": "A small number that matter.", "cluster": "conditions"}, {"key": "c", "label": "Only if something concerns us", "description": "Not by default.", "cluster": "minimal"}, {"key": "d", "label": "Keep it simple", "description": "No added conditions.", "cluster": "minimal"}]'::jsonb,
    'Conditions are a normal part of the contract, not a sign of mistrust. Try naming one each, and see how it feels to say it.'),
  ('1a5e9566-c456-5d83-b540-689a1dd8992a', '0fbc17fb-1ee6-572c-b31d-d06775fe562c', 'nikah-04', 4, 'What would you want the ceremony to be like?',
    '[{"key": "a", "label": "Small and simple", "description": "The nikah and little else.", "cluster": "small"}, {"key": "b", "label": "Modest, close family", "description": "Intimate but celebrated.", "cluster": "small"}, {"key": "c", "label": "A large celebration", "description": "Wide invitation, full walima.", "cluster": "large"}, {"key": "d", "label": "Whatever our families want", "description": "Their day as much as ours.", "cluster": "large"}]'::jsonb,
    'Wedding size is where family expectation lands hardest. Agree your position as a pair before either family is consulted.'),
  ('de904bc3-fe24-5183-9631-8e5b036ee019', '0fbc17fb-1ee6-572c-b31d-d06775fe562c', 'nikah-05', 5, 'When should we write wills?',
    '[{"key": "a", "label": "Soon after the nikah", "description": "Straight away.", "cluster": "early"}, {"key": "b", "label": "Within a year or two", "description": "Once we''re settled.", "cluster": "early"}, {"key": "c", "label": "When we have children or assets", "description": "When there''s something to direct.", "cluster": "later"}, {"key": "d", "label": "Haven''t thought about it", "description": "Not on my radar yet.", "cluster": "later"}]'::jsonb,
    'Islamic inheritance and local law don''t always align, and a will is what reconciles them. Worth one appointment early rather than a problem later.'),
  ('e2795d87-f2c7-5fd7-b2b3-3da8728fc057', '0fbc17fb-1ee6-572c-b31d-d06775fe562c', 'nikah-06', 6, 'How involved should families be in the nikah itself?',
    '[{"key": "a", "label": "Fully involved", "description": "Throughout, from start to finish.", "cluster": "involved"}, {"key": "b", "label": "In the formal parts", "description": "Present for the contract and ceremony.", "cluster": "involved"}, {"key": "c", "label": "Informed, decisions ours", "description": "Kept in the loop, not deciding.", "cluster": "limited"}, {"key": "d", "label": "Minimal", "description": "As small a role as possible.", "cluster": "limited"}]'::jsonb,
    'The wali has a defined role; everything beyond it is custom. Separate the two before deciding what you each expect.'),
  ('73f3f467-e0d3-5947-815d-84fe16197d91', '90fb0b64-1bdc-5036-957b-ec41e04b58a6', 'health-01', 1, 'How do you feel about health screening before the nikah?',
    '[{"key": "a", "label": "Both of us, beforehand", "description": "As a matter of course.", "cluster": "proactive"}, {"key": "b", "label": "If there''s a family reason", "description": "Where history suggests it.", "cluster": "proactive"}, {"key": "c", "label": "Only if advised", "description": "If a doctor recommends it.", "cluster": "reactive"}, {"key": "d", "label": "I''d rather not", "description": "Not something I''d want.", "cluster": "reactive"}]'::jsonb,
    'Screening is common practice in many communities and unfamiliar in others. Talk about what each of you grew up seeing as normal.'),
  ('74282c92-8563-5c4c-8604-16389dd4fe06', '90fb0b64-1bdc-5036-957b-ec41e04b58a6', 'health-02', 2, 'How much health history should we share with each other?',
    '[{"key": "a", "label": "Everything, before we commit", "description": "Fully open from the start.", "cluster": "full"}, {"key": "b", "label": "Anything affecting our life together", "description": "What''s relevant to us.", "cluster": "full"}, {"key": "c", "label": "What''s current", "description": "Present, not past.", "cluster": "partial"}, {"key": "d", "label": "Health is personal", "description": "Shared when I choose to.", "cluster": "partial"}]'::jsonb,
    'There''s a difference between owed and offered. Agree what each of you would consider unfair to learn late.'),
  ('49734a91-ed95-56d8-8559-558902ab62ac', '90fb0b64-1bdc-5036-957b-ec41e04b58a6', 'health-03', 3, 'If one of us had a long-term condition, what would you want?',
    '[{"key": "a", "label": "Every detail, early", "description": "Full picture upfront.", "cluster": "early"}, {"key": "b", "label": "The outline early", "description": "Broad strokes now, detail over time.", "cluster": "early"}, {"key": "c", "label": "When it becomes relevant", "description": "As and when it affects us.", "cluster": "gradual"}, {"key": "d", "label": "Learn as we go", "description": "No formal disclosure.", "cluster": "gradual"}]'::jsonb,
    'This is about pace, not secrecy. Say what you''d want to know before the nikah versus after, and why.'),
  ('514a64c1-5497-53ff-af13-a99ac27cf3a4', '90fb0b64-1bdc-5036-957b-ec41e04b58a6', 'health-04', 4, 'How do you feel about counselling or therapy?',
    '[{"key": "a", "label": "Normal and welcome", "description": "I''d use it without hesitation.", "cluster": "open"}, {"key": "b", "label": "Fine, after other things", "description": "Not the first port of call.", "cluster": "open"}, {"key": "c", "label": "I''d turn to family or an imam", "description": "Support from people who know us.", "cluster": "informal"}, {"key": "d", "label": "I''d handle things privately", "description": "I work through things alone.", "cluster": "informal"}]'::jsonb,
    'How each of you seeks help matters most when things are hardest. Agree one route you''d both accept in advance.'),
  ('f1b662de-5ca3-5bc1-829d-6fe9da7f4caa', '90fb0b64-1bdc-5036-957b-ec41e04b58a6', 'health-05', 5, 'What role do health habits play in your life?',
    '[{"key": "a", "label": "A big priority", "description": "Exercise, food and sleep are structured.", "cluster": "active"}, {"key": "b", "label": "Something I try to keep up", "description": "On and off.", "cluster": "moderate"}, {"key": "c", "label": "Not a focus", "description": "Other things take precedence.", "cluster": "moderate"}, {"key": "d", "label": "Something I''d want us to build together", "description": "Easier as a pair.", "cluster": "active"}]'::jsonb,
    'Habits are contagious in both directions in a marriage. Pick one you''d both be glad to catch.'),
  ('56d186a0-9a50-5daa-a5e9-19988f131ebc', '90fb0b64-1bdc-5036-957b-ec41e04b58a6', 'health-06', 6, 'If one of us were seriously unwell, what would care look like?',
    '[{"key": "a", "label": "Hands-on, whatever it takes", "description": "I''d be the one caring.", "cluster": "personal"}, {"key": "b", "label": "Present, with family helping", "description": "Shared across the family.", "cluster": "personal"}, {"key": "c", "label": "Practical support, professional care", "description": "Bring in help where needed.", "cluster": "supported"}, {"key": "d", "label": "I haven''t thought about it", "description": "Genuinely unsure.", "cluster": "supported"}]'::jsonb,
    'Nobody knows this until it happens, and that''s worth saying aloud. Agree only that you''d decide it together rather than assume.'),
  ('bdbef3a4-a00e-528a-b694-128ce82e4683', 'a949b8a2-6e65-5287-ae3c-14befd30e21b', 'work-01', 1, 'How should our careers relate to each other?',
    '[{"key": "a", "label": "One leads, one supports", "description": "A clear primary career.", "cluster": "led"}, {"key": "b", "label": "We take turns", "description": "Whoever has the opportunity.", "cluster": "balanced"}, {"key": "c", "label": "Both equal, always", "description": "Neither takes precedence.", "cluster": "balanced"}, {"key": "d", "label": "Higher earner takes priority", "description": "Decided by income.", "cluster": "led"}]'::jsonb,
    'Whichever you choose, it should be a decision rather than a drift. Agree how you''d revisit it every couple of years.'),
  ('c3ad9c5b-145f-59c7-8292-83354f2c39d7', 'a949b8a2-6e65-5287-ae3c-14befd30e21b', 'work-02', 2, 'What working pattern do you want?',
    '[{"key": "a", "label": "Standard hours, evenings free", "description": "Work stays at work.", "cluster": "contained"}, {"key": "b", "label": "Long hours, for now", "description": "Intense while it''s worth it.", "cluster": "intense"}, {"key": "c", "label": "Flexible or self-employed", "description": "My own schedule.", "cluster": "intense"}, {"key": "d", "label": "As few as we can afford", "description": "Work to live.", "cluster": "contained"}]'::jsonb,
    'Working patterns decide how much of each other you actually get. Compare a real week, hour by hour.'),
  ('c594e68b-d478-5aa2-8fb2-6ceba616b578', 'a949b8a2-6e65-5287-ae3c-14befd30e21b', 'work-03', 3, 'Would you relocate for work?',
    '[{"key": "a", "label": "Anywhere", "description": "No geographic limits.", "cluster": "mobile"}, {"key": "b", "label": "Within the country", "description": "Nationally, but not abroad.", "cluster": "mobile"}, {"key": "c", "label": "Only nearby", "description": "Commutable at most.", "cluster": "rooted"}, {"key": "d", "label": "No", "description": "I''d change job before I moved.", "cluster": "rooted"}]'::jsonb,
    'Compare this against your answers in Living arrangements — if they disagree, one of them isn''t true yet.'),
  ('38aa125f-d549-5dfd-ab43-f62a1c2e4f3b', 'a949b8a2-6e65-5287-ae3c-14befd30e21b', 'work-04', 4, 'How much work travel is acceptable?',
    '[{"key": "a", "label": "Regularly, fine", "description": "Part of the job.", "cluster": "high"}, {"key": "b", "label": "Occasionally", "description": "A few times a year.", "cluster": "high"}, {"key": "c", "label": "Rarely and short", "description": "A night or two at most.", "cluster": "low"}, {"key": "d", "label": "I''d rather neither of us did", "description": "Home every night.", "cluster": "low"}]'::jsonb,
    'Travel is easier before children and harder after. Say what your answer would be in each case.'),
  ('e4c54d03-1ff9-54fd-b337-71245344af53', 'a949b8a2-6e65-5287-ae3c-14befd30e21b', 'work-05', 5, 'If one of us wanted to start a business, what then?',
    '[{"key": "a", "label": "Full support, including money", "description": "We''d back it properly.", "cluster": "supportive"}, {"key": "b", "label": "Support, with a plan", "description": "Yes, with limits agreed.", "cluster": "supportive"}, {"key": "c", "label": "Once we''re secure", "description": "Not until there''s a cushion.", "cluster": "cautious"}, {"key": "d", "label": "I''d be uneasy", "description": "The risk would worry me.", "cluster": "cautious"}]'::jsonb,
    'Risk tolerance rarely matches between two people. Agree a figure you''d both be willing to lose, not a feeling.'),
  ('72276ffc-0b20-578e-9eb9-dceed881c04f', 'a949b8a2-6e65-5287-ae3c-14befd30e21b', 'work-06', 6, 'What do you expect around providing for the household?',
    '[{"key": "a", "label": "The husband provides", "description": "Anything else is a bonus.", "cluster": "traditional"}, {"key": "b", "label": "Both contribute", "description": "In whatever proportion works.", "cluster": "shared"}, {"key": "c", "label": "Whoever is best placed", "description": "It may change over time.", "cluster": "shared"}, {"key": "d", "label": "Both earning throughout", "description": "Neither of us stops.", "cluster": "shared"}]'::jsonb,
    'There''s a difference between obligation and arrangement. Separate what you believe is owed from what you''d actually want day to day.'),
  ('8e36dee2-1a27-542b-9f16-7017f3ae7b7d', 'c55ff2dc-8bf8-5fa8-90c0-f1c205cc89f6', 'social-01', 1, 'How much time out with friends after marriage?',
    '[{"key": "a", "label": "As before", "description": "Marriage doesn''t change it.", "cluster": "unchanged"}, {"key": "b", "label": "Less, but regular", "description": "Reduced, still there.", "cluster": "unchanged"}, {"key": "c", "label": "Occasionally", "description": "Now and then.", "cluster": "reduced"}, {"key": "d", "label": "Mostly together or with family", "description": "Our time comes first.", "cluster": "reduced"}]'::jsonb,
    'Losing friendships quietly is a common cost of early marriage. Agree a night each that''s protected rather than negotiated.'),
  ('d9726f10-6bdb-5fd2-8a38-b71653895900', 'c55ff2dc-8bf8-5fa8-90c0-f1c205cc89f6', 'social-02', 2, 'How do you view friendships with the opposite gender?',
    '[{"key": "a", "label": "Not something I''d keep", "description": "I''d step back from them.", "cluster": "closed"}, {"key": "b", "label": "Professional or family only", "description": "Contexts with a clear reason.", "cluster": "closed"}, {"key": "c", "label": "Fine, with openness", "description": "As long as nothing is hidden.", "cluster": "open"}, {"key": "d", "label": "Fine, and normal", "description": "No particular issue.", "cluster": "open"}]'::jsonb,
    'This is one of the most common sources of quiet friction. Describe a specific situation rather than a rule, and see whether you agree on that.'),
  ('8afc4997-50f5-56bf-a58a-2d7846244700', 'c55ff2dc-8bf8-5fa8-90c0-f1c205cc89f6', 'social-03', 3, 'Phones and privacy between us?',
    '[{"key": "a", "label": "Fully open", "description": "Nothing hidden, either way.", "cluster": "open"}, {"key": "b", "label": "Open, not monitored", "description": "Available, but not checked.", "cluster": "open"}, {"key": "c", "label": "Private, with trust", "description": "We each keep our own space.", "cluster": "private"}, {"key": "d", "label": "Private, and checking would be a problem", "description": "It would breach something.", "cluster": "private"}]'::jsonb,
    'Both positions can be healthy; mismatched expectations rarely are. Say what you''d feel if the other''s answer were the rule.'),
  ('2465f294-54a9-5209-b2b5-4c1953328a3e', 'c55ff2dc-8bf8-5fa8-90c0-f1c205cc89f6', 'social-04', 4, 'How public should our life be?',
    '[{"key": "a", "label": "Not posted at all", "description": "Nothing about us online.", "cluster": "private"}, {"key": "b", "label": "Occasional, nothing personal", "description": "Rare and general.", "cluster": "private"}, {"key": "c", "label": "Comfortable sharing", "description": "Our life is visible.", "cluster": "public"}, {"key": "d", "label": "No strong feeling", "description": "Happy either way.", "cluster": "public"}]'::jsonb,
    'Agree a simple rule: nothing about the other person without asking. It removes most of the friction on its own.'),
  ('53fe003f-3b8b-5538-9249-41773df1dc11', 'c55ff2dc-8bf8-5fa8-90c0-f1c205cc89f6', 'social-05', 5, 'What does a free weekend look like?',
    '[{"key": "a", "label": "Just us", "description": "Time as a pair.", "cluster": "couple"}, {"key": "b", "label": "With extended family", "description": "The usual gathering.", "cluster": "family"}, {"key": "c", "label": "With friends", "description": "Social and out.", "cluster": "family"}, {"key": "d", "label": "Separately, our own things", "description": "Space to do our own.", "cluster": "separate"}]'::jsonb,
    'Weekends are the whole relationship for most working couples. Try dividing a month into four and assigning each one.'),
  ('ac668a30-920c-5e45-88da-150cfc8cfe2c', 'c55ff2dc-8bf8-5fa8-90c0-f1c205cc89f6', 'social-06', 6, 'If one of us were uncomfortable with the other''s friendship, what then?',
    '[{"key": "a", "label": "I''d expect it to end", "description": "Discomfort is enough.", "cluster": "act"}, {"key": "b", "label": "I''d expect it to change", "description": "Adjusted, not ended.", "cluster": "act"}, {"key": "c", "label": "A conversation, not a decision", "description": "Talk about it, decide after.", "cluster": "discuss"}, {"key": "d", "label": "My judgment trusted", "description": "I''d want to be believed.", "cluster": "discuss"}]'::jsonb,
    'This is really about how much weight discomfort carries on its own. Agree what the first conversation would sound like.'),
  ('4edceafa-b577-5bdd-9b51-8f45427d01dd', '9874cf09-8f3b-5c29-a26d-fddc1690ac0f', 'deal-01', 1, 'If we wanted fundamentally different things about children?',
    '[{"key": "a", "label": "It would end this", "description": "I couldn''t move past it.", "cluster": "hard"}, {"key": "b", "label": "We''d need serious help first", "description": "Not without support.", "cluster": "hard"}, {"key": "c", "label": "We''d work through it", "description": "Over time, together.", "cluster": "workable"}, {"key": "d", "label": "I''d adapt", "description": "I could live with either.", "cluster": "workable"}]'::jsonb,
    'You''ve marked this differently, which means one of you is holding more weight here than the other realises. Start there rather than with the answers.'),
  ('7df10379-2531-50e9-8adc-ec25bb64147c', '9874cf09-8f3b-5c29-a26d-fddc1690ac0f', 'deal-02', 2, 'Living permanently far from your family?',
    '[{"key": "a", "label": "Couldn''t accept it", "description": "A genuine limit.", "cluster": "hard"}, {"key": "b", "label": "Very hard, but possible", "description": "With difficulty.", "cluster": "hard"}, {"key": "c", "label": "Manageable", "description": "I''d adjust.", "cluster": "workable"}, {"key": "d", "label": "Fine", "description": "No real issue.", "cluster": "workable"}]'::jsonb,
    'Distance is one of the few things here you can plan around precisely. Talk about visits and frequency rather than the principle.'),
  ('aa85a8c3-72d0-503e-87ea-3367d492bb2a', '9874cf09-8f3b-5c29-a26d-fddc1690ac0f', 'deal-03', 3, 'If a real difference in religious practice developed over time?',
    '[{"key": "a", "label": "I couldn''t continue", "description": "It''s foundational for me.", "cluster": "hard"}, {"key": "b", "label": "We''d need help", "description": "Guidance from someone we trust.", "cluster": "hard"}, {"key": "c", "label": "I''d accept it with difficulty", "description": "Hard, but not the end.", "cluster": "workable"}, {"key": "d", "label": "I''d accept it", "description": "People change.", "cluster": "workable"}]'::jsonb,
    'Practice shifts in both directions over a marriage, and usually slowly. Talk about what support would look like rather than what the outcome would be.'),
  ('cb7c7860-20ce-5317-a8d8-0a570441d5b3', '9874cf09-8f3b-5c29-a26d-fddc1690ac0f', 'deal-04', 4, 'Significant debt discovered after the nikah?',
    '[{"key": "a", "label": "A serious breach of trust", "description": "The hiding, more than the debt.", "cluster": "hard"}, {"key": "b", "label": "Difficult, but we''d handle it", "description": "We''d deal with it together.", "cluster": "workable"}, {"key": "c", "label": "Depends on the amount", "description": "Scale matters.", "cluster": "workable"}, {"key": "d", "label": "Not a major issue", "description": "Debt is normal.", "cluster": "workable"}]'::jsonb,
    'The fix here is disclosure, not tolerance. Set a date before the nikah when you''ll both say your actual numbers.'),
  ('a0b0427b-fda4-5a1f-b599-ed988568f657', '9874cf09-8f3b-5c29-a26d-fddc1690ac0f', 'deal-05', 5, 'If one of us changed our mind about working after children?',
    '[{"key": "a", "label": "A serious problem", "description": "It would change the arrangement fundamentally.", "cluster": "hard"}, {"key": "b", "label": "We''d renegotiate carefully", "description": "Hard, but solvable.", "cluster": "workable"}, {"key": "c", "label": "We''d adapt", "description": "Plans change.", "cluster": "workable"}, {"key": "d", "label": "Expected", "description": "Nobody knows until they''re there.", "cluster": "workable"}]'::jsonb,
    'Almost everyone revises this once a child arrives. Agree now that a change of mind is allowed, and how it would be handled.'),
  ('5dd69d67-eb70-50e1-8524-617a37d23b8a', '9874cf09-8f3b-5c29-a26d-fddc1690ac0f', 'deal-06', 6, 'What would you most want your partner to know is non-negotiable for you?',
    '[{"key": "a", "label": "Faith and how we practise", "description": "The foundation for me.", "cluster": "faith"}, {"key": "b", "label": "Family and their place in our life", "description": "They come with me.", "cluster": "family"}, {"key": "c", "label": "Honesty, always", "description": "I could forgive most things but not hiding.", "cluster": "honesty"}, {"key": "d", "label": "Freedom to pursue my own work", "description": "I need to keep building something.", "cluster": "work"}]'::jsonb,
